use rhwp::DocumentCore;use serde_json::{json,Value};
fn state(d:&DocumentCore)->Value{json!((0..d.page_count()).map(|p|json!({"controls":serde_json::from_str::<Value>(&d.get_page_control_layout_native(p).unwrap()).unwrap(),"text":serde_json::from_str::<Value>(&d.get_page_text_layout_native(p).unwrap()).unwrap()})).collect::<Vec<_>>())}
fn same(a:&Value,b:&Value,p:&str){match(a,b){(Value::Number(a),Value::Number(b))=>assert!((a.as_f64().unwrap()-b.as_f64().unwrap()).abs()<=0.2,"{p}: {a} != {b}"),(Value::Array(a),Value::Array(b))=>{assert_eq!(a.len(),b.len(),"{p}");for(i,(a,b))in a.iter().zip(b).enumerate(){same(a,b,&format!("{p}/{i}"));}},(Value::Object(a),Value::Object(b))=>{assert_eq!(a.keys().collect::<Vec<_>>(),b.keys().collect::<Vec<_>>(),"{p}");for(k,a)in a{same(a,&b[k],&format!("{p}/{k}"));}},_=>assert_eq!(a,b,"{p}")}}
fn cell_format(mode:&str,actual:bool){let path=if actual{format!("../hancom-current/{mode}.hwp")}else if mode=="negative"{format!("../support/{mode}.hwp")}else{format!("../final-inputs/{mode}.hwp")};let bytes=std::fs::read(path).unwrap();let mut d=DocumentCore::from_bytes(&bytes).unwrap();let before=state(&d);let undo=d.save_snapshot_native();d.apply_char_format_in_cell_native(0,2,0,0,0,0,1,r#"{"fontSize":1100}"#).unwrap();let shape_id=match &d.document().sections[0].paragraphs[2].controls[0]{rhwp::model::control::Control::Table(t)=>t.cells[0].paragraphs[0].char_shapes.iter().find(|s|s.start_pos==0).unwrap().char_shape_id as usize,_=>panic!()};assert_eq!(d.document().doc_info.char_shapes[shape_id].base_size,1100,"intended 11pt property is actually applied");let nested_dirty=match &d.document().sections[0].paragraphs[2].controls[0]{rhwp::model::control::Control::Table(t)=>t.cells[0].paragraphs[0].cell_format_vpos_dirty,_=>panic!()};let after=state(&d);assert_ne!(before,after,"actual cell formatting changes published glyph properties");let redo=d.save_snapshot_native();d.restore_snapshot_native(undo).unwrap();same(&before,&state(&d),"actual cell-format undo");d.restore_snapshot_native(redo).unwrap();same(&after,&state(&d),"actual cell-format redo");for hwpx in[false,true]{let first=checked_export(&d,hwpx);let one=DocumentCore::from_bytes(&first).unwrap();same(&after,&state(&one),"actual dirty cell first strict save/reopen");let second=checked_export(&one,hwpx);let two=DocumentCore::from_bytes(&second).unwrap();same(&after,&state(&two),"actual dirty cell second strict save/reopen");}std::fs::create_dir_all("../actual-cell-format-v8").unwrap();std::fs::write(format!("../actual-cell-format-v8/{mode}-{actual}.json"),serde_json::to_vec_pretty(&json!({"mode":mode,"actualSource":actual,"nativeCellFormatApplied":true,"nestedDirtyBeforeRender":nested_dirty,"undoRedoFullGeometry":true,"twoCyclesBothFormats":true})).unwrap()).unwrap();}
#[test]fn negative_original_cell(){cell_format("negative",false)}#[test]fn negative_hancom_cell(){cell_format("negative",true)}#[test]fn positive_original_cell(){cell_format("offset",false)}#[test]fn positive_hancom_cell(){cell_format("offset",true)}
fn checked_export(d:&DocumentCore,hwpx:bool)->Vec<u8>{
 let before=serde_json::to_vec(&d.document().sections.iter().map(|s|&s.paragraphs).collect::<Vec<_>>()).unwrap();
 let report=if hwpx{d.export_hwpx_native_with_report().unwrap()}else{d.export_hwp_with_adapter_snapshot_with_report().unwrap()};
 assert!(report.content_loss().is_empty(),"genuine content loss must not be ignored: {}",report.content_loss().to_json());
 let bytes=report.into_bytes();let reopened=DocumentCore::from_bytes(&bytes).unwrap();
 let a:Value=serde_json::from_str(&d.get_document_metadata_native()).unwrap();let b:Value=serde_json::from_str(&reopened.get_document_metadata_native()).unwrap();assert_eq!(a["values"],b["values"],"all five metadata fields preserved");
 assert_eq!(before,serde_json::to_vec(&d.document().sections.iter().map(|s|&s.paragraphs).collect::<Vec<_>>()).unwrap(),"export cannot mutate the original paragraph/control tree");bytes
}
